1	#!/usr/bin/env node
2	/**
3	 * Nxeon in-browser VNC console — websocket relay.
4	 *
5	 * A tiny standalone process that bridges a browser noVNC websocket to a
6	 * Proxmox `vncwebsocket` endpoint. The browser never receives the Proxmox API
7	 * token or the raw VNC ticket — those arrive here inside an encrypted JWE
8	 * (issued by app/api/console/[serverId]/route.ts) which only this relay, which
9	 * shares AUTH_SECRET with the web app, can decrypt.
10	 *
11	 *   browser  ──ws──▶  console-proxy  ──wss──▶  Proxmox /vncwebsocket
12	 *            (noVNC)   (holds creds)           (VNC RFB stream)
13	 *
14	 * DEPENDENCIES: only Node built-ins (http, tls, crypto, url) + `jose` (already
15	 * a project dependency — used for JWE). The `ws` npm package is NOT required;
16	 * the WebSocket framing (server-accept handshake, client handshake, frame
17	 * encode/decode, masking, fragmentation, ping/pong) is implemented below.
18	 *
19	 * ENV (read from the same /opt/nxeon/.env as the web app):
20	 *   AUTH_SECRET          shared secret — must match the web app (required)
21	 *   CONSOLE_PROXY_PORT   listen port (default 8899)
22	 *   CONSOLE_PROXY_HOST   listen address (default 0.0.0.0)
23	 *
24	 * Run: node scripts/console-proxy.mjs
25	 */
26	
27	import http from "node:http";
28	import tls from "node:tls";
29	import { createHash, randomBytes } from "node:crypto";
30	import { jwtDecrypt } from "jose";
31	
32	const PORT = Number(process.env.CONSOLE_PROXY_PORT ?? 8899);
33	const HOST = process.env.CONSOLE_PROXY_HOST ?? "0.0.0.0";
34	const WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
35	
36	// 256-bit JWE key derived identically to the web app (lib route consoleKey()).
37	function consoleKey() {
38	  const secret = process.env.AUTH_SECRET;
39	  if (!secret) {
40	    console.error("[console-proxy] FATAL: AUTH_SECRET not set");
41	    process.exit(1);
42	  }
43	  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
44	}
45	const KEY = consoleKey();
46	
47	// Single-use ticket tracking: jti -> expiry(ms). A ticket may be redeemed once.
48	const usedJti = new Map();
49	setInterval(() => {
50	  const now = Date.now();
51	  for (const [jti, exp] of usedJti) if (exp < now) usedJti.delete(jti);
52	}, 30_000).unref();
53	
54	/* ------------------------------------------------------------------ *
55	 *  Minimal WebSocket framing over a raw duplex socket.
56	 *  `maskOut`: true when we act as a WS *client* (browser→Proxmox side must
57	 *  mask per RFC 6455); false when we act as a WS *server* (frames to the
58	 *  browser must NOT be masked).
59	 * ------------------------------------------------------------------ */
60	class WsConn {
61	  constructor(socket, maskOut, name) {
62	    this.socket = socket;
63	    this.maskOut = maskOut;
64	    this.name = name;
65	    this.buf = Buffer.alloc(0);
66	    this.fragOpcode = 0;
67	    this.fragChunks = [];
68	    this._handler = null; // (opcode, payload:Buffer) => void
69	    this._pending = []; // messages received before a handler is bound
70	    this.onclose = null;
71	    this.closed = false;
72	
73	    socket.on("data", (chunk) => {
74	      this.buf = this.buf.length ? Buffer.concat([this.buf, chunk]) : chunk;
75	      try {
76	        this._parse();
77	      } catch (err) {
78	        console.error(`[console-proxy] frame parse error on ${name}:`, err.message);
79	        this.close();
80	      }
81	    });
82	    socket.on("close", () => this._fireClose());
83	    socket.on("error", () => this._fireClose());
84	  }
85	
86	  _fireClose() {
87	    if (this.closed) return;
88	    this.closed = true;
89	    if (this.onclose) this.onclose();
90	  }
91	
92	  /** Bind the message handler and flush anything buffered before it was set.
93	   *  Guards against dropping frames a peer sends before the other leg is up. */
94	  bind(handler) {
95	    this._handler = handler;
96	    const q = this._pending;
97	    this._pending = [];
98	    for (const [op, p] of q) handler(op, p);
99	  }
100	
101	  _emit(opcode, payload) {
102	    if (this._handler) this._handler(opcode, payload);
103	    else this._pending.push([opcode, payload]);
104	  }
105	
106	  _parse() {
107	    for (;;) {
108	      const b = this.buf;
109	      if (b.length < 2) return;
110	      const b0 = b[0];
111	      const b1 = b[1];
112	      const fin = (b0 & 0x80) !== 0;
113	      const opcode = b0 & 0x0f;
114	      const masked = (b1 & 0x80) !== 0;
115	      let len = b1 & 0x7f;
116	      let offset = 2;
117	      if (len === 126) {
118	        if (b.length < 4) return;
119	        len = b.readUInt16BE(2);
120	        offset = 4;
121	      } else if (len === 127) {
122	        if (b.length < 10) return;
123	        len = Number(b.readBigUInt64BE(2));
124	        offset = 10;
125	      }
126	      let maskKey;
127	      if (masked) {
128	        if (b.length < offset + 4) return;
129	        maskKey = b.subarray(offset, offset + 4);
130	        offset += 4;
131	      }
132	      const total = offset + len;
133	      if (b.length < total) return;
134	      let payload = Buffer.from(b.subarray(offset, total)); // copy — buf gets sliced
135	      if (masked) {
136	        for (let i = 0; i < payload.length; i++) payload[i] ^= maskKey[i & 3];
137	      }
138	      this.buf = b.subarray(total);
139	      this._handleFrame(fin, opcode, payload);
140	    }
141	  }
142	
143	  _handleFrame(fin, opcode, payload) {
144	    if (opcode === 0x8) {
145	      // close
146	      this.close();
147	      return;
148	    }
149	    if (opcode === 0x9) {
150	      // ping -> reply pong on same socket, and swallow
151	      this._send(0xa, payload);
152	      return;
153	    }
154	    if (opcode === 0xa) return; // pong -> ignore
155	
156	    // data (0x1 text, 0x2 binary) or continuation (0x0)
157	    if (opcode === 0x0) {
158	      this.fragChunks.push(payload);
159	      if (fin) {
160	        const full = Buffer.concat(this.fragChunks);
161	        const op = this.fragOpcode || 0x2;
162	        this.fragChunks = [];
163	        this.fragOpcode = 0;
164	        this._emit(op, full);
165	      }
166	      return;
167	    }
168	    if (fin) {
169	      this._emit(opcode, payload);
170	    } else {
171	      this.fragOpcode = opcode;
172	      this.fragChunks = [payload];
173	    }
174	  }
175	
176	  /** Encode + write a single (unfragmented) frame. */
177	  _send(opcode, payload) {
178	    if (this.closed || this.socket.destroyed) return;
179	    const len = payload.length;
180	    let header;
181	    if (len < 126) {
182	      header = Buffer.alloc(2);
183	      header[1] = len;
184	    } else if (len < 65536) {
185	      header = Buffer.alloc(4);
186	      header[1] = 126;
187	      header.writeUInt16BE(len, 2);
188	    } else {
189	      header = Buffer.alloc(10);
190	      header[1] = 127;
191	      header.writeBigUInt64BE(BigInt(len), 2);
192	    }
193	    header[0] = 0x80 | opcode; // FIN + opcode
194	
195	    if (this.maskOut) {
196	      header[1] |= 0x80;
197	      const mask = randomBytes(4);
198	      const masked = Buffer.allocUnsafe(len);
199	      for (let i = 0; i < len; i++) masked[i] = payload[i] ^ mask[i & 3];
200	      this.socket.write(Buffer.concat([header, mask, masked]));
201	    } else {
202	      this.socket.write(Buffer.concat([header, payload]));
203	    }
204	  }
205	
206	  /** Public: forward an application message (preserves text/binary opcode). */
207	  send(opcode, payload) {
208	    this._send(opcode === 0x1 ? 0x1 : 0x2, payload);
209	  }
210	
211	  close() {
212	    if (this.closed) {
213	      try {
214	        this.socket.destroy();
215	      } catch {}
216	      return;
217	    }
218	    try {
219	      this._send(0x8, Buffer.alloc(0));
220	    } catch {}
221	    try {
222	      this.socket.end();
223	    } catch {}
224	    this._fireClose();
225	  }
226	}
227	
228	/* ------------------------------------------------------------------ *
229	 *  Open a WebSocket client connection to Proxmox's vncwebsocket endpoint
230	 *  over TLS. Resolves with a connected WsConn (client role, masks output).
231	 * ------------------------------------------------------------------ */
232	function connectProxmox(target) {
233	  return new Promise((resolve, reject) => {
234	    const u = new URL(target.apiBase);
235	    const host = u.hostname;
236	    const port = Number(u.port || 8006);
237	
238	    const path =
239	      `/api2/json/nodes/${encodeURIComponent(target.node)}` +
240	      `/qemu/${target.vmid}/vncwebsocket` +
241	      `?port=${encodeURIComponent(String(target.port))}` +
242	      `&vncticket=${encodeURIComponent(target.vncticket)}`;
243	
244	    const key = randomBytes(16).toString("base64");
245	    const auth = `PVEAPIToken=${target.tokenId}=${target.tokenSecret}`;
246	
247	    // Only set SNI servername for real hostnames — RFC 6066 forbids IP literals.
248	    const isIp = /^[0-9.]+$/.test(host) || host.includes(":");
249	    const socket = tls.connect(
250	      { host, port, servername: isIp ? undefined : host, rejectUnauthorized: false },
251	      () => {
252	        const reqLines = [
253	          `GET ${path} HTTP/1.1`,
254	          `Host: ${host}:${port}`,
255	          "Upgrade: websocket",
256	          "Connection: Upgrade",
257	          "Sec-WebSocket-Version: 13",
258	          `Sec-WebSocket-Key: ${key}`,
259	          "Sec-WebSocket-Protocol: binary",
260	          `Authorization: ${auth}`,
261	          `Cookie: PVEAuthCookie=`,
262	          "",
263	          "",
264	        ];
265	        socket.write(reqLines.join("\r\n"));
266	      }
267	    );
268	
269	    let handshakeBuf = Buffer.alloc(0);
270	    const onHandshakeData = (chunk) => {
271	      handshakeBuf = Buffer.concat([handshakeBuf, chunk]);
272	      const idx = handshakeBuf.indexOf("\r\n\r\n");
273	      if (idx === -1) {
274	        if (handshakeBuf.length > 16384) {
275	          socket.destroy();
276	          reject(new Error("Proxmox handshake too large"));
277	        }
278	        return;
279	      }
280	      const head = handshakeBuf.subarray(0, idx).toString("latin1");
281	      const rest = handshakeBuf.subarray(idx + 4);
282	      socket.removeListener("data", onHandshakeData);
283	
284	      const statusLine = head.split("\r\n")[0] || "";
285	      if (!/ 101 /.test(statusLine)) {
286	        socket.destroy();
287	        reject(new Error(`Proxmox refused websocket: ${statusLine.trim()}`));
288	        return;
289	      }
290	      const conn = new WsConn(socket, /* maskOut */ true, "proxmox");
291	      // Any bytes already buffered after the headers belong to the ws stream.
292	      if (rest.length) socket.emit("data", rest);
293	      resolve(conn);
294	    };
295	    socket.on("data", onHandshakeData);
296	    socket.on("error", (err) => reject(err));
297	    socket.setTimeout(15_000, () => {
298	      socket.destroy();
299	      reject(new Error("Proxmox connection timed out"));
300	    });
301	    socket.on("secureConnect", () => socket.setTimeout(0));
302	  });
303	}
304	
305	/* ------------------------------------------------------------------ *
306	 *  HTTP server: accepts the browser websocket upgrade on /console.
307	 * ------------------------------------------------------------------ */
308	const server = http.createServer((_req, res) => {
309	  // Plain health check for the systemd unit / nginx.
310	  res.writeHead(200, { "Content-Type": "text/plain" });
311	  res.end("nxeon console-proxy ok\n");
312	});
313	
314	server.on("upgrade", async (req, socket) => {
315	  const url = new URL(req.url, "http://localhost");
316	  if (url.pathname !== "/console") {
317	    socket.destroy();
318	    return;
319	  }
320	
321	  const sid = url.searchParams.get("sid");
322	  const wsKey = req.headers["sec-websocket-key"];
323	  if (!sid || !wsKey) {
324	    socket.write("HTTP/1.1 400 Bad Request\r\n\r\n");
325	    socket.destroy();
326	    return;
327	  }
328	
329	  // Decrypt + validate the ticket (auth, expiry, single use).
330	  let target;
331	  try {
332	    const { payload } = await jwtDecrypt(sid, KEY, { clockTolerance: 5 });
333	    const jti = payload.jti;
334	    if (!jti || usedJti.has(jti)) throw new Error("ticket already used");
335	    // exp is in seconds; keep for cleanup slightly beyond.
336	    usedJti.set(jti, (payload.exp ?? Math.floor(Date.now() / 1000) + 60) * 1000 + 60_000);
337	    target = payload;
338	  } catch (err) {
339	    console.warn("[console-proxy] rejected ticket:", err.message);
340	    socket.write("HTTP/1.1 401 Unauthorized\r\n\r\n");
341	    socket.destroy();
342	    return;
343	  }
344	
345	  // Complete the browser-side WebSocket handshake.
346	  const accept = createHash("sha1")
347	    .update(wsKey + WS_GUID)
348	    .digest("base64");
349	  const respHeaders = [
350	    "HTTP/1.1 101 Switching Protocols",
351	    "Upgrade: websocket",
352	    "Connection: Upgrade",
353	    `Sec-WebSocket-Accept: ${accept}`,
354	  ];
355	  // noVNC always requests the "binary" subprotocol — echo it back.
356	  const wantProto = String(req.headers["sec-websocket-protocol"] || "");
357	  if (wantProto.split(",").map((s) => s.trim()).includes("binary")) {
358	    respHeaders.push("Sec-WebSocket-Protocol: binary");
359	  }
360	  respHeaders.push("", "");
361	  socket.write(respHeaders.join("\r\n"));
362	
363	  const browser = new WsConn(socket, /* maskOut */ false, "browser");
364	
365	  // Connect to Proxmox, then pipe both directions.
366	  let pve;
367	  try {
368	    pve = await connectProxmox(target);
369	  } catch (err) {
370	    console.error("[console-proxy] Proxmox connect failed:", err.message);
371	    browser.close();
372	    return;
373	  }
374	
375	  console.log(`[console-proxy] session open: vmid=${target.vmid} node=${target.node}`);
376	
377	  browser.bind((op, data) => pve.send(op, data));
378	  pve.bind((op, data) => browser.send(op, data));
379	  browser.onclose = () => {
380	    pve.close();
381	    console.log(`[console-proxy] session closed (browser): vmid=${target.vmid}`);
382	  };
383	  pve.onclose = () => {
384	    browser.close();
385	    console.log(`[console-proxy] session closed (proxmox): vmid=${target.vmid}`);
386	  };
387	});
388	
389	server.on("clientError", (_err, socket) => {
390	  try {
391	    socket.destroy();
392	  } catch {}
393	});
394	
395	server.listen(PORT, HOST, () => {
396	  console.log(`[console-proxy] listening on ws://${HOST}:${PORT}/console`);
397	});
