128	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
129	const MAX_FORWARDS_PER_SERVER = 10;
130	
131	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
132	  const serverId = String(formData.get("serverId") ?? "");
133	  const { user, server } = await ownedServer(serverId);
134	  const parsed = z
135	    .object({
136	      guestPort: z.coerce.number().int().min(1).max(65535),
137	      protocol: z.enum(["tcp", "udp"]),
138	    })
139	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
140	  if (!parsed.success) return { error: "Invalid port." };
141	
142	  const count = await db.portForward.count({ where: { serverId } });
143	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
144	
145	  const used = new Set([
146	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
147	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
148	  ]);
149	  let publicPort = 0;
150	  for (let p = PF_MIN; p <= PF_MAX; p++) {
151	    if (!used.has(p)) { publicPort = p; break; }
152	  }
153	  if (!publicPort) return { error: "No public ports available." };
154	
155	  await db.portForward.create({
156	    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
157	  });
158	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
159	  await db.auditLog.create({
160	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
161	  });
162	  revalidatePath(`/dashboard/servers/${serverId}`);
163	  return {};
164	}
