82	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
83	async function scheduleNode(planRamMB: number) {
84	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
85	  if (nodes.length === 0) return null;
86	  const loads = await Promise.all(
87	    nodes.map(async (n) => {
88	      const agg = await db.server.findMany({
89	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
90	        select: { plan: { select: { ramMB: true } } },
91	      });
92	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
93	      return { node: n, free: n.capacityRamMB - used };
94	    })
95	  );
96	  loads.sort((a, b) => b.free - a.free);
97	  const best = loads[0];
98	  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
99	  return best.node;
100	}
