106	    osTemplateId: formData.get("osTemplateId"),
107	    hostname: formData.get("hostname"),
108	  });
109	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid input." };
110	
111	  const plan = await db.plan.findUnique({ where: { id: parsed.data.planId } });
112	  const os = await db.osTemplate.findUnique({ where: { id: parsed.data.osTemplateId } });
113	  if (!plan?.active || !os?.active) return { error: "Plan or OS not available." };
114	
115	  // Image requirements (control panels/apps need more resources)
116	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
117	    return {
118	      error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
119	    };
120	  }
121	
122	  const cap = await capacityCheck(plan.id);
123	  if (!cap.ok) return { error: cap.reason };
