209	export async function serverAction(serverId: string, action: string) {
210	  const { user, server } = await ownedServer(serverId);
211	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
212	    start: "START",
213	    stop: "STOP",
214	    reboot: "REBOOT",
215	    reinstall: "REINSTALL",
216	    delete: "DELETE",
217	  };
218	  const type = allowed[action];
219	  if (!type) throw new Error("Invalid action");
220	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
221	    throw new Error("Server is suspended");
222	  }
223	
224	  const pending = await db.job.count({
