232	  await db.job.create({ data: { type, serverId } });
233	  await audit(user.id, `server.${action}`, serverId);
234	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
235	  revalidatePath(`/dashboard/servers/${serverId}`);
