11	/**
12	 * Admin CRUD + health checks for compute nodes (Proxmox hypervisors).
13	 *
14	 * Multi-node correctness rules enforced here:
15	 *  - Each node lives in its own NAT /24 (`subnetPrefix`). Two nodes may reuse
16	 *    the same guest-IP range ONLY if they sit in different subnets — so we only
17	 *    flag an IP overlap when the subnetPrefix matches.
18	 *  - SSH DNAT forwards happen on each node's own host, so port ranges may repeat
19	 *    across different hosts. They only conflict when two Node rows point at the
20	 *    same public IP (same host) with overlapping port ranges.
21	 *  - `natChain` is the iptables chain the worker rebuilds from the DB; it must be
22	 *    globally unique so one node's rebuild never clobbers another's rules.
23	 */
24	
25	type FormState = { error?: string; ok?: boolean };
26	
27	async function audit(userId: string | null, action: string, detail?: string) {
28	  await db.auditLog.create({ data: { userId, action, detail } });
29	}
30	
31	function rangesOverlap(aStart: number, aEnd: number, bStart: number, bEnd: number): boolean {
32	  return aStart <= bEnd && bStart <= aEnd;
33	}
34	
35	/** Suggest sane, non-colliding defaults for the Nth node (1-based ordinal of the new node). */
36	export async function suggestNodeDefaults(): Promise<{
37	  ordinal: number;
38	  subnetPrefix: string;
39	  natChain: string;
40	  ipStart: number;
41	  ipEnd: number;
42	  sshPortStart: number;
43	  sshPortEnd: number;
44	}> {
45	  await requireAdmin();
46	  const count = await db.node.count();
47	  const ordinal = count + 1;
48	  // node #1 → 10.20.0. / NXEON_FWD ; node #2 → 10.20.1. / NXEON_FWD_N2 ; ...
49	  const subnetPrefix = `10.20.${ordinal - 1}.`;
50	  const natChain = ordinal === 1 ? "NXEON_FWD" : `NXEON_FWD_N${ordinal}`;
51	  return { ordinal, subnetPrefix, natChain, ipStart: 100, ipEnd: 250, sshPortStart: 20000, sshPortEnd: 29999 };
52	}
