83	    pveNode: (formData.get("pveNode") ?? "").toString().trim(),
84	    apiUrl: (formData.get("apiUrl") ?? "").toString().trim(),
85	    tokenId: (formData.get("tokenId") ?? "").toString().trim(),
86	    tokenSecret: (formData.get("tokenSecret") ?? "").toString().trim(),
87	    publicIp: (formData.get("publicIp") ?? "").toString().trim(),
88	    bridge: (formData.get("bridge") ?? "vmbr1").toString().trim(),
89	    subnetPrefix: (formData.get("subnetPrefix") ?? "").toString().trim(),
90	    ipStart: formData.get("ipStart"),
91	    ipEnd: formData.get("ipEnd"),
92	    sshPortStart: formData.get("sshPortStart"),
93	    sshPortEnd: formData.get("sshPortEnd"),
94	    natChain: (formData.get("natChain") ?? "").toString().trim(),
95	    storageNvme: (formData.get("storageNvme") ?? "vmdata").toString().trim(),
96	    storageHdd: (formData.get("storageHdd") ?? "vmdata-hdd").toString().trim(),
97	    capacityRamMB: formData.get("capacityRamMB"),
