21	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
22	
23	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
24	  const user = await requireUser();
25	  if (!registrarConfigured()) {
26	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
27	  }
28	  const contactSchema = z.object({
29	    firstName: z.string().min(1).max(60),
30	    lastName: z.string().min(1).max(60),
31	    address1: z.string().min(1).max(120),
32	    city: z.string().min(1).max(60),
33	    stateProvince: z.string().min(1).max(60),
34	    postalCode: z.string().min(1).max(20),
35	    country: z.string().length(2),
36	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
37	    email: z.string().email(),
38	  });
39	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
40	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
41	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
42	
43	  const contactParsed = contactSchema.safeParse({
44	    firstName: formData.get("firstName"),
45	    lastName: formData.get("lastName"),
46	    address1: formData.get("address1"),
47	    city: formData.get("city"),
48	    stateProvince: formData.get("stateProvince"),
49	    postalCode: formData.get("postalCode"),
50	    country: String(formData.get("country") ?? "").toUpperCase(),
51	    phone: formData.get("phone"),
52	    email: formData.get("email"),
53	  });
54	  if (!contactParsed.success) {
55	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
56	  }
57	
58	  if (await db.domain.findUnique({ where: { name: domain } })) {
59	    return { error: "This domain is already managed by another account." };
60	  }
61	
62	  // Live availability + price from name.com
63	  let priceCents: number;
64	  try {
65	    const [check] = await checkDomains([domain]);
66	    if (!check) return { error: "Could not check availability. Try again." };
67	    if (!check.available) return { error: "Domain is not available." };
68	    if (check.premium) return { error: "Premium domains are not supported yet." };
69	    if (check.priceCents === null) return { error: "No price available for this TLD." };
70	    priceCents = check.priceCents;
71	  } catch (e: any) {
72	    return { error: String(e?.message ?? e).slice(0, 200) };
73	  }
74	
75	  const totalCents = domainTermPriceCents(priceCents, dTerm.years);
76	  if (user.balanceCents < totalCents) {
77	    return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
78	  }
79	
80	  const record = await db.$transaction(async (tx) => {
81	    await tx.user.update({ where: { id: user.id }, data: { balanceCents: { decrement: totalCents } } });
82	    await tx.walletTransaction.create({
83	      data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
84	    });
85	    return tx.domain.create({
86	      data: { name: domain, userId: user.id, priceCents, termYears: dTerm.years, status: "PENDING", registrar: "name.com" },
87	    });
88	  });
89	
90	  try {
91	    const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, totalCents);
92	    const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
93	    await db.domain.update({
94	      where: { id: record.id },
95	      data: {
96	        status: "ACTIVE",
97	        registeredAt: new Date(),
98	        expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
99	      },
100	    });
101	    await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
102	    await db.notification.create({
103	      data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
104	    });
105	  } catch (e: any) {
106	    await db.$transaction([
107	      db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
108	      db.walletTransaction.create({
109	        data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
110	      }),
111	      db.domain.update({
112	        where: { id: record.id },
113	        data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 500) },
114	      }),
115	    ]);
116	    return { error: `Registration failed: ${String(e?.message ?? e).slice(0, 200)} (you were refunded).` };
117	  }
118	  redirect(`/dashboard/domains/${record.id}`);
119	}
