33	    take: 4,
34	  });
35	  for (const d of domains) {
36	    results.push({ type: "domain", label: d.name, sub: d.status.toLowerCase(), href: `/dashboard/domains/${d.id}` });
37	  }
38	
39	  const tickets = await db.ticket.findMany({
