46	/**
47	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
48	 * plus any control-panel/app install script and selected add-ons. Long installs
49	 * run in the background so the VM reports ready promptly.
50	 */
51	function buildCloudInit(server: any): string {
52	  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
53	  const setup: string[] = [];
54	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
55	  if (addons.malwareScanner)
56	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
57	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
58	
59	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
60	  return `#cloud-config
61	package_update: true
62	packages:
63	  - qemu-guest-agent
64	ssh_pwauth: true
65	disable_root: false
66	write_files:
67	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
68	    permissions: "0644"
69	    content: |
70	      PermitRootLogin yes
71	      PasswordAuthentication yes
72	  - path: /root/nxeon-setup.sh
73	    permissions: "0755"
74	    content: |
75	${indentBlock(script, 6)}
76	runcmd:
77	  - systemctl enable --now qemu-guest-agent
78	  - systemctl restart ssh || systemctl restart sshd
79	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
80	`;
81	}
