88	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
89	
90	  const { conn, row: nodeRow } = await nodeFor(server);
91	  const storage = server.plan.storageTier === "hdd"
92	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
93	    : nodeRow?.storageNvme ?? "vmdata";
94	
95	  const vmid = server.vmid ?? (await conn.nextVmid());
96	  const ip = server.ipAddress ?? (await allocateIp());
97	  const sshPort = server.sshPort ?? (await allocateSshPort());
98	  const password = generatePassword();
99	
100	  await db.server.update({
101	    where: { id: server.id },
102	    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
103	  });
104	
105	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
106	  const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
107	    newid: vmid,
108	    name: server.hostname,
109	    full: 1,
110	    storage,
111	  });
112	  await conn.waitForTask(cloneUpid, 600_000);
113	
114	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
115	  const snippet = buildCloudInit(server);
116	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
117	    console.error("[worker] snippet write failed", e)
118	  );
119	
120	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
121	  const sshkeys = keys.length
122	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
123	    : undefined;
124	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, {
125	    cores: server.plan.cpuCores,
126	    memory: server.plan.ramMB,
127	    ciuser: "root",
128	    cipassword: password,
129	    sshkeys,
130	    ipconfig0: `ip=${ip}/24,gw=${gatewayIp()}`,
131	    nameserver: "1.1.1.1 8.8.8.8",
132	    onboot: 1,
133	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
134	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
135	  });
136	
137	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
138	    disk: "scsi0",
139	    size: `${server.plan.diskGB}G`,
140	  });
141	
142	  await syncPortForwards();
143	
144	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
145	  await conn.waitForTask(startUpid);
146	
147	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
148	  const isImage = server.osTemplate.category !== "PLAIN_OS";
149	  await notify(
150	    server.userId,
151	    `Server ${server.hostname} is ready`,
152	    isImage
153	      ? `${server.osTemplate.name} is installing in the background (a few minutes). SSH: ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`
154	      : `SSH: ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`,
155	    `/dashboard/servers/${server.id}`
156	  );
157	}
