267	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
268	  const server = await loadServer(job);
269	  const payload = (job.payload ?? {}) as { name?: string };
270	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
271	  if (!name) throw new Error("snapshot: invalid name");
272	  let upid: string;
273	  if (op === "create") {
274	    upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/snapshot`, { snapname: name });
275	  } else if (op === "delete") {
276	    upid = await pve.del(`/nodes/${node}/qemu/${server.vmid}/snapshot/${name}`);
277	  } else {
278	    upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
279	  }
280	  await waitForTask(upid, 600_000);
281	  if (op === "rollback") {
282	    // rollback leaves the VM stopped; bring it back if the server should be running
283	    const current = await db.server.findUnique({ where: { id: server.id } });
284	    if (current?.status === "RUNNING") {
285	      try {
286	        const startUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/start`, {});
287	        await waitForTask(startUpid);
288	      } catch { /* may already be running */ }
289	    }
290	  }
291	}
