293	async function passwordReset(job: Job) {
294	  const server = await loadServer(job);
295	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
296	  const password = generatePassword();
297	
298	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
299	  let applied = false;
300	  try {
301	    const upid = await pve.post(
302	      `/nodes/${node}/qemu/${server.vmid}/agent/set-user-password`,
303	      { username: "root", password }
304	    );
305	    // agent endpoints return a UPID on this cluster; wait if so, otherwise it's synchronous.
306	    if (typeof upid === "string" && upid.startsWith("UPID")) await waitForTask(upid);
307	    applied = true;
308	  } catch (e) {
309	    console.error("[worker] agent set-user-password failed, falling back to cloud-init", e);
310	  }
311	
312	  // Fallback: rewrite cloud-init password and reboot so it reapplies.
313	  if (!applied) {
314	    await pve.post(`/nodes/${node}/qemu/${server.vmid}/config`, { cipassword: password });
315	    if (server.status === "RUNNING") {
316	      const upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/reboot`, {});
317	      await waitForTask(upid);
318	    }
319	  }
320	
321	  await db.server.update({ where: { id: server.id }, data: { rootPassword: password } });
322	  await notify(
323	    server.userId,
324	    `Root password reset for ${server.hostname}`,
325	    "Your new root password is available on the server's Overview tab.",
326	    `/dashboard/servers/${server.id}`
327	  );
328	}
