330	async function backupCreate(job: Job) {
331	  const server = await loadServer(job);
332	  const upid = await pve.post(`/nodes/${node}/vzdump`, {
333	    vmid: server.vmid,
334	    storage: "backup",
335	    mode: "snapshot",
336	    compress: "zstd",
337	  });
338	  await waitForTask(upid, 3_600_000);
339	  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
340	    `/dashboard/servers/${server.id}`);
341	}
