343	const handlers: Record<string, (job: Job) => Promise<void>> = {
344	  PROVISION: provision,
345	  START: (j) => powerAction(j, "start"),
346	  STOP: (j) => powerAction(j, "stop"),
347	  REBOOT: (j) => powerAction(j, "reboot"),
348	  DELETE: remove,
349	  REINSTALL: reinstall,
350	  SUSPEND: (j) => suspend(j, false),
351	  UNSUSPEND: (j) => suspend(j, true),
352	  RESIZE: resize,
353	  SNAPSHOT_CREATE: (j) => snapshotOp(j, "create"),
354	  SNAPSHOT_DELETE: (j) => snapshotOp(j, "delete"),
355	  SNAPSHOT_ROLLBACK: (j) => snapshotOp(j, "rollback"),
356	  BACKUP_CREATE: backupCreate,
357	  PASSWORD_RESET: passwordReset,
358	  SYNC_FORWARDS: async () => syncPortForwards(),
359	};
