361	async function runJob(job: Job) {
362	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
363	  await db.job.update({
364	    where: { id: job.id },
365	    data: { status: "RUNNING", attempts: { increment: 1 } },
366	  });
367	  try {
368	    await handlers[job.type](job);
369	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
370	    console.log(`[worker] job ${job.id} DONE`);
371	  } catch (e: any) {
372	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
373	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
374	    const current = await db.job.findUnique({ where: { id: job.id } });
375	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
376	    await db.job.update({
377	      where: { id: job.id },
378	      data: { status: retriable ? "QUEUED" : "FAILED", error },
379	    });
380	    if (!retriable && job.serverId) {
381	      const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
382	      if (stillExists) {
383	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
384	      }
385	    }
386	  }
387	}
