1	import { db } from "../lib/db";
2	import { registrarConfigured, renewDomain } from "../lib/registrar";
3	import { vpsTerm, vpsTermPriceCents, domainTerm, domainTermPriceCents, addMonths } from "../lib/billing-terms";
4	
5	const GRACE_DAYS = 3;
6	const RENEW_DAYS = 30;
7	const DOMAIN_RENEW_WINDOW_DAYS = 7;
8	
9	/**
10	 * Subscription sweep, run periodically by the worker:
11	 *  - expired + autoRenew + sufficient balance  -> charge wallet, extend 30 days
12	 *  - expired beyond grace (or autoRenew off)   -> queue SUSPEND with unpaid note
13	 * Free servers (isFree) are never touched.
14	 */
15	export async function billingSweep() {
16	  const now = new Date();
17	
18	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
19	  const soon = new Date(now.getTime() + 3 * 86400_000);
20	  const upcoming = await db.server.findMany({
21	    where: {
22	      isFree: false,
23	      expiresAt: { gt: now, lt: soon },
24	      status: { in: ["RUNNING", "STOPPED"] },
25	    },
26	    include: { plan: true, user: true },
27	  });
28	  for (const server of upcoming) {
29	    if (server.autoRenew && server.user.balanceCents >= vpsTermPriceCents(server.plan.priceCents, server.termMonths)) continue;
30	    const already = await db.notification.findFirst({
31	      where: {
32	        userId: server.userId,
33	        title: { contains: server.hostname },
34	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
35	        AND: { title: { contains: "renews soon" } },
36	      },
37	    });
38	    if (!already) {
39	      await db.notification.create({
40	        data: {
41	          userId: server.userId,
42	          title: `${server.hostname} renews soon — action needed`,
43	          body: server.autoRenew
44	            ? `Renewal is $${(server.plan.priceCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
45	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
46	          href: `/dashboard/servers/${server.id}`,
47	        },
48	      });
49	    }
50	  }
51	  const due = await db.server.findMany({
52	    where: {
53	      isFree: false,
54	      expiresAt: { lt: now },
55	      status: { in: ["RUNNING", "STOPPED"] },
56	    },
57	    include: { plan: true, user: true },
58	  });
59	
60	  for (const server of due) {
61	    const graceEnd = new Date(server.expiresAt!.getTime() + GRACE_DAYS * 86400_000);
62	    const renewTerm = vpsTerm(server.termMonths);
63	    const renewCents = vpsTermPriceCents(server.plan.priceCents, renewTerm.months);
64	
65	    if (server.autoRenew && server.user.balanceCents >= renewCents) {
66	      const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
67	      const newExpiry = addMonths(base, renewTerm.months);
68	      await db.$transaction([
69	        db.user.update({
70	          where: { id: server.userId },
71	          data: { balanceCents: { decrement: renewCents } },
72	        }),
73	        db.walletTransaction.create({
74	          data: {
75	            userId: server.userId,
76	            amountCents: -renewCents,
77	            description: `Renewal: ${server.plan.name} VPS (${server.hostname}) — ${renewTerm.label}`,
78	          },
79	        }),
80	        db.server.update({
81	          where: { id: server.id },
82	          data: { expiresAt: newExpiry },
83	        }),
84	        db.auditLog.create({
85	          data: { userId: server.userId, action: "billing.renewed", detail: server.id },
86	        }),
87	      ]);
88	      console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
89	    } else if (now > graceEnd) {
90	      const pending = await db.job.count({
91	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
92	      });
93	      if (pending === 0) {
94	        await db.server.update({
95	          where: { id: server.id },
96	          data: { suspendedNote: "unpaid — renew from your billing page to restore access" },
97	        });
