118	/**
119	 * Auto-renew domains expiring within 7 days when the owner opted in and has
120	 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
121	 * Failures (registrar error, misconfig) notify the owner to renew manually and
122	 * never charge the wallet.
123	 */
124	async function domainAutoRenewSweep(now: Date) {
125	  if (!registrarConfigured()) return; // registrar not configured — skip silently
126	
127	  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
128	  const domains = await db.domain.findMany({
129	    where: {
130	      autoRenew: true,
131	      status: "ACTIVE",
132	      expiresAt: { not: null, lt: cutoff },
133	    },
134	    include: { user: true },
135	  });
136	
137	  for (const domain of domains) {
138	    if (!domain.expiresAt) continue;
139	    const dTerm = domainTerm(domain.termYears);
140	    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
141	    if (domain.user.balanceCents < dRenewCents) {
142	      const already = await db.notification.findFirst({
143	        where: {
144	          userId: domain.userId,
145	          title: { contains: domain.name },
146	          AND: { title: { contains: "auto-renew failed" } },
147	          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
148	        },
149	      });
150	      if (!already) {
151	        await db.notification.create({
152	          data: {
153	            userId: domain.userId,
154	            title: `${domain.name} auto-renew failed — top up to renew`,
155	            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
156	            href: `/dashboard/domains`,
157	          },
158	        });
159	      }
160	      continue;
161	    }
162	
163	    try {
164	      await renewDomain(domain.name, dTerm.years, dRenewCents);
165	    } catch (e) {
166	      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
167	      await db.notification.create({
168	        data: {
169	          userId: domain.userId,
170	          title: `${domain.name} auto-renew failed — please renew manually`,
171	          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
172	          href: `/dashboard/domains`,
173	        },
174	      });
175	      continue;
176	    }
177	
178	    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
179	    await db.$transaction([
180	      db.user.update({
181	        where: { id: domain.userId },
182	        data: { balanceCents: { decrement: dRenewCents } },
183	      }),
184	      db.walletTransaction.create({
185	        data: {
186	          userId: domain.userId,
187	          amountCents: -dRenewCents,
188	          description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
189	        },
190	      }),
191	      db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } }),
192	      db.auditLog.create({
193	        data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
194	      }),
195	    ]);
196	    await db.notification.create({
197	      data: {
198	        userId: domain.userId,
199	        title: `${domain.name} renewed automatically`,
200	        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
201	        href: `/dashboard/domains`,
202	      },
203	    });
204	    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
205	  }
206	}
